#include <bits/stdc++.h>
using namespace std;

const int N = 100 + 5;
const long long INF = 1000000000000000LL;

long long d[N][N];
long long dt[N][N];
long long t[N][N];
long long r[N][N];
int a[N];
int n;
long long T;

void one(long long a[][N]) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            a[i][j] = 0;
}

void copy(long long a[][N], long long b[][N]) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            b[i][j] = a[i][j];
}

void mul(long long a[][N], long long b[][N], long long c[][N]) {
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            c[i][j] = -INF;
            for (int k = 0; k < n; ++k) {
                c[i][j] = max(c[i][j], a[i][k] + b[k][j]);
            }
        }
    }
}

void binpow(long long a[][N], long long b, long long c[][N]) {
    copy(a, t);
    one(c);
    while (b != 0) {
        if (b & 1) {
            mul(c, t, r);
            copy(r, c);
        }
        mul(t, t, r);
        copy(r, t);
        b >>= 1;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n >> T;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    for (int s = 0; s < n; ++s) {
        for (int i = 0; i < n; ++i) {
            if (a[i] < a[s]) {
                d[s][i] = -INF;
            } else {
                d[s][i] = 1;
                for (int j = 0; j < i; ++j) {
                    if (a[j] <= a[i]) {
                        d[s][i] = max(d[s][i], d[s][j] + 1);
                    }
                }
            }
        }
    }

    binpow(d, T, dt);

    long long res = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            res = max(res, dt[i][j]);
        }
    }

    cout << res << "\n";
    return 0;
}

